{
  "bioavailability_prediction": "high",
  "confidence": "moderate",
  "revision_action": "keep",
  "supportive_card_ids": ["C11","C45","C63","C90","C01","C28","C17","C16","C22","C36","C08","C13","C02"],
  "contradictory_card_ids": ["C76","C82","C86","C68","C47"],
  "prediction_basis_card_ids": ["C11","C45","C63","C90","C01","C28","C17","C16","C22","C36","C08","C13","C02"],
  "claims": [
    {
      "claim": "The query has no direct oral bioavailability measurement; the closest visible anilinopyrimidine context is nilotinib, whose fasted human absolute bioavailability is assumed to be 31%, with L2 records reiterating about 31% and attributing low absorption to precipitation under fasted conditions.",
      "card_ids": ["C11","C45","C63","C90"]
    },
    {
      "claim": "All direct human absolute or systemic bioavailability values in visible contexts are at or above 31%, including risperidone about 68-70%, brexpiprazole 95%, daridorexant 62%, bidisomide 42.6-61%, PNU-96391 60%, bitopertin high, mofarotene high, and compound 12 predicted 67%.",
      "card_ids": ["C01","C28","C17","C16","C22","C36","C08","C13","C02"]
    },
    {
      "claim": "Low F values in visible contexts are rodent or suspension specific, such as daridorexant rat 9%, bitopertin rat 14-23%, and risperidone rat 19%, and do not provide transferable affirmative evidence that human F is below 20%.",
      "card_ids": ["C76","C82","C86","C68","C47"]
    },
    {
      "claim": "L3 oral exposure records for imatinib, erlotinib, bazedoxifene, dasatinib, torsemide, and a dacomitinib metabolite show measurable plasma exposure after oral dosing, but they lack intravenous comparators and do not report absolute bioavailability for the query or for these molecules.",
      "card_ids": ["C95","C100","C107","C122","C127","C104","C124","C119","C113","C120"]
    },
    {
      "claim": "The physicochemical prior is mixed, but no affirmative threshold-relevant evidence supports F below 20%, so high remains better supported.",
      "card_ids": ["C11","C45","C63"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "low",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C95","C100","C107","C122","C127","C104","C124","C119","C113","C120"]
    }
  ],
  "evidence_gaps": [
    "No direct oral bioavailability measurement exists for the query molecule.",
    "No L3 record measures the query molecule; all L3 records are exposure-only data for other molecules.",
    "Structural similarity to nilotinib or imatinib is qualitative; the query has a basic pyrrolidinylethoxy group and a tert-butylsulfonamide.",
    "No direct solubility, permeability, first-pass metabolism, or efflux data are available for the query.",
    "Low rodent F values are species and formulation specific and cannot be directly extrapolated to human oral bioavailability."
  ],
  "decision_summary": "L3 adds only oral exposure records for other molecules without intravenous comparators or F endpoints, so it does not provide affirmative evidence for F below 20%. The closest nilotinib context gives fasted human F of 31%, and all direct human F values in visible contexts are at or above 31%. Low rodent values are species and formulation specific. Therefore high remains better supported with moderate confidence."
}

